    public void lastCharIsWhitespace_ReturnsTrueWhenLastCharacterIsWhitespace() {
        StringBuilder sb = new StringBuilder(" \t\n\r");
        assertTrue(StringUtil.lastCharIsWhitespace(sb));
    }

